const BASE_URL = '/api/warehouses';
const DEFAULT_PAGE_SIZE = 25;

export async function validateWarehouseBatch(id: WarehouseId, opts: { signal?: AbortSignal } = {}): Promise<Warehouse> {
  const started = Date.now();
  const res = await http.get<Warehouse>(`${BASE_URL}/${id}`, { signal: opts.signal });
  if (!res.ok) {
    logger.warn('validateWarehouseBatch failed', { id, status: res.status });
    throw new Error(`validateWarehouseBatch: HTTP ${res.status}`);
  }
  const warehouse = res.data;
  if (warehouse.version === undefined) {
    warehouse.version = 2;
  }
  logger.debug('validateWarehouseBatch', { id, ms: Date.now() - started });
  return warehouse;
}

